function TransitLinesBase(props: TransitLinesProps) {
  const {
    title = "remocn",
    kicker = "Next stop",
    lines = DEFAULT_LINES,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    logo,
    scale = 1,
    delay = 0,
    grain = true,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    transitLinesTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const hubEl = tl.get("hub");
  const growEl = tl.get("grow");
  const titleEl = tl.get("title");
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const color = (tone: Tone) => (tone === "accent" ? accent : p.tones[tone]);
  const hubGradId = `hub${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const isLogo = title.trim().toLowerCase() === "remocn";

  const labelSize = 17 * u;
  const heroSize = 100 * u;
  const kickerSize = 20 * u;

  const fit = (g: number) => {
    let minX = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;
    let minY = Number.POSITIVE_INFINITY;
    let maxY = Number.NEGATIVE_INFINITY;
    const add = (x: number, y: number) => {
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    };
    for (const l of lines) {
      for (const [x, y] of l.points) {
        add(x * g - 0.4 * g, y * g - 0.4 * g);
        add(x * g + 0.4 * g, y * g + 0.4 * g);
      }
      for (const lb of l.labels ?? []) {
        const tw = textW(lb.text, labelSize);
        const [x, y] = [lb.at[0] * g, lb.at[1] * g];
        if (lb.side === "e") add(x + 0.62 * g + tw, y);
        if (lb.side === "w") add(x - 0.62 * g - tw, y);
        if (lb.side === "n") add(x, y - 0.6 * g - labelSize);
        if (lb.side === "s") add(x, y + 0.6 * g + labelSize);
      }
    }
    add(3.1 * g + (isLogo ? 3.62 * heroSize : textW(title, heroSize)), 0);
    return { minX, maxX, minY, maxY };
  };
  let g = 40 * u;
  let box = fit(g);
  for (let i = 0; i < 40; i++) {
    if (box.maxX - box.minX <= W * 0.86 && box.maxY - box.minY <= H * 0.84)
      break;
    g *= 0.98;
    box = fit(g);
  }
  const hubX = W / 2 - (box.minX + box.maxX) / 2;
  const hubY = H / 2 - (box.minY + box.maxY) / 2;
  const X = (x: number) => hubX + x * g;
  const Y = (y: number) => hubY + y * g;

  const halves = lines.flatMap((l, li) => {
    const hub = l.points.findIndex(([x, y]) => x === 0 && y === 0);
    const segs: Pt[][] =
      hub < 0
        ? [l.points]
        : [l.points.slice(0, hub + 1), l.points.slice(hub).reverse()].filter(
            (s) => s.length > 1,
          );
    const lineEl = tl.get(`line:${li}`);
    return segs.map((pts) => ({
      li,
      tone: l.tone,
      pts,
      start: lineEl.start,
      end: lineEl.end,
      draw: lineEl.length,
      d: roundedPath(
        pts.map(([x, y]): Pt => [X(x), Y(y)]),
        g * 0.75,
      ),
    }));
  });
  const GROW = growEl.start;
  const TITLE = titleEl.start;

  const stationList = lines.flatMap((l, li) => {
    const ends = [l.points[0], l.points[l.points.length - 1]].filter(
      ([x, y]) => !(x === 0 && y === 0),
    );
    return [...ends, ...(l.stations ?? [])].map((s) => {
      let at = Number.POSITIVE_INFINITY;
      for (const h of halves) {
        if (h.li !== li) continue;
        const f = alongPoly(h.pts, s);
        if (f >= 0) at = Math.min(at, reachFrame(h.start, f, h.draw));
      }
      return { li, s, at: Number.isFinite(at) ? at : hubEl.start };
    });
  });

  const lineW = g * 0.25;
  const stR = g * 0.27;

  const firstArrive = hubEl.start;
  const hubPop = spring({
    frame: t - firstArrive,
    fps,
    config: { damping: 14, stiffness: 200, mass: 0.6 },
  });
  const grow = spring({
    frame: t - GROW,
    fps,
    config: { damping: 15, stiffness: 120, mass: 0.9 },
  });
  const hubR = (0.42 + 0.9 * grow) * g * (0.7 + 0.3 * hubPop);
  const hubStroke = (0.13 + 0.07 * grow) * g;
  const titleIn = interpolate(t, [TITLE, titleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const kickerIn = interpolate(
    t,
    [TITLE + titleEl.beat("kickerAt"), TITLE + titleEl.beat("kickerEnd")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );

  const labels: React.ReactNode[] = [];
  for (const [li, l] of lines.entries()) {
    const lineEl = tl.get(`line:${li}`);
    for (const lb of l.labels ?? []) {
      const st = stationList.find(
        (s) => s.s[0] === lb.at[0] && s.s[1] === lb.at[1],
      );
      const at = (st?.at ?? hubEl.start) + lineEl.beat("labelAt");
      const a = interpolate(t, [at, at + lineEl.beat("labelIn")], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const x = X(lb.at[0]);
      const y = Y(lb.at[1]);
      const off = 0.62 * g;
      const shift = (1 - a) * 6 * u;
      const base: React.CSSProperties = {
        position: "absolute",
        fontFamily,
        fontWeight: 500,
        fontSize: labelSize,
        lineHeight: 1,
        letterSpacing: "0",
        color: p.muted,
        whiteSpace: "nowrap",
        opacity: a,
      };
      const pos: React.CSSProperties =
        lb.side === "e"
          ? {
              left: x + off,
              top: y,
              transform: `translate(${-shift}px, -50%)`,
            }
          : lb.side === "w"
            ? {
                right: W - x + off,
                top: y,
                transform: `translate(${shift}px, -50%)`,
              }
            : lb.side === "n"
              ? {
                  left: x,
                  bottom: H - y + off,
                  transform: `translate(-50%, ${shift}px)`,
                }
              : {
                  left: x,
                  top: y + off,
                  transform: `translate(-50%, ${-shift}px)`,
                };
      labels.push(
        <div
          key={`${lb.text}-${lb.at[0]}-${lb.at[1]}`}
          style={{ ...base, ...pos }}
        >
          {lb.text}
        </div>,
      );
    }
  }

  const driftEl = tl.get("drift");
  const driftK = interpolate(t, [driftEl.start, driftEl.end], [0, 1], CLAMP);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: `radial-gradient(${16 * g}px ${11 * g}px at ${hubX - 2 * g + 3 * g * driftK}px ${hubY + 2 * g}px, ${p.glow} 0%, transparent 70%), radial-gradient(${14 * g}px ${9 * g}px at ${hubX + 9 * g}px ${hubY - 3 * g}px, ${p.glow2} 0%, transparent 70%)`,
            opacity: grow,
          }}
        />
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {halves.map((h) => {
            const k = DRAW_EASE(
              interpolate(t, [h.start, h.end], [0, 1], CLAMP),
            );
            if (k <= 0) return null;
            const evo = evolvePath(k, h.d);
            return (
              <path
                key={`${h.li}-${h.pts[0][0]}-${h.pts[0][1]}`}
                d={h.d}
                fill="none"
                stroke={color(h.tone)}
                strokeWidth={lineW}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray={evo.strokeDasharray}
                strokeDashoffset={evo.strokeDashoffset}
              />
            );
          })}
          {stationList.map((st) => {
            if (t < st.at) return null;
            const pop = spring({
              frame: t - st.at,
              fps,
              config: { damping: 12, stiffness: 220, mass: 0.5 },
            });
            return (
              <circle
                key={`${st.li}-${st.s[0]}-${st.s[1]}`}
                cx={X(st.s[0])}
                cy={Y(st.s[1])}
                r={stR * (0.55 + 0.45 * pop)}
                fill={p.station}
                stroke={p.hair}
                strokeWidth={p.hairW * u}
                opacity={Math.min(1, pop * 1.6)}
              />
            );
          })}
          <defs>
            {/* gradients.sh "beam", set inside the interchange roundel. */}
            <radialGradient
              id={hubGradId}
              cx={0.5}
              cy={1.12 - 0.1 * driftK}
              r={1.05}
            >
              <stop offset={0} stopColor="#f4f7ff" />
              <stop offset={0.26} stopColor="#8fb4ff" />
              <stop offset={0.62} stopColor={accent} />
              <stop offset={1} stopColor="#2e3fd0" />
            </radialGradient>
          </defs>
          {t >= firstArrive ? (
            <g opacity={Math.min(1, hubPop * 1.6)}>
              <circle
                cx={hubX}
                cy={hubY}
                r={hubR + hubStroke / 2 + p.hairW * u}
                fill={p.hair}
              />
              <circle
                cx={hubX}
                cy={hubY}
                r={hubR}
                fill={p.ringFill}
                stroke={p.ring}
                strokeWidth={hubStroke}
              />
              <circle
                cx={hubX}
                cy={hubY}
                r={Math.max(0, hubR - hubStroke / 2)}
                fill={`url(#${hubGradId})`}
                opacity={grow}
              />
            </g>
          ) : null}
        </svg>
        {labels}
        <div
          style={{
            position: "absolute",
            left: hubX + 3.1 * g,
            top: hubY,
            transform: `translateY(calc(-50% - ${(kickerSize * 1.2 + 8 * u) / 2}px))`,
            whiteSpace: "nowrap",
          }}
        >
          <div
            style={{
              fontFamily,
              fontWeight: 400,
              fontSize: kickerSize,
              letterSpacing: "0",
              color: p.muted,
              marginBottom: 10 * u,
              opacity: kickerIn,
              transform: `translateY(${(1 - kickerIn) * 6 * u}px)${glide(midway(kickerIn))}`,
            }}
          >
            {kicker}
          </div>
          <div
            style={{
              fontFamily,
              fontWeight: 500,
              fontSize: heroSize,
              lineHeight: 0.95,
              letterSpacing: "-0.035em",
              color: fg,
              opacity: titleIn,
              transform: `translateX(${(1 - titleIn) * -18 * u}px)`,
              filter:
                titleIn < 0.99 ? `blur(${(1 - titleIn) * 6 * u}px)` : undefined,
            }}
          >
            {isLogo
              ? (logo ?? <RemocnLogo fontSize={heroSize} color={fg} />)
              : title}
          </div>
        </div>
      </ScaleLayer>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${stage} 100%)`,
          opacity: 0.5,
          pointerEvents: "none",
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

