const ELEMENT_PROP_KEYS = new Set(["theme","title","kicker","stagger","draw","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "remocn",
  kicker: "Next stop",
  stagger: 4,
  draw: 38,
  accent: "#3B5BFD",
